  const t = String(s).replace(/O/g, '0').replace(/\s/g, '').replace(',', '.');
  const m = t.match(/^([0-9]+)(?:\.([0-9]{1,2}))?$/);
  if (!m) return null;
  return parseInt(m[1], 10) * 100 + parseInt(((m[2] || '') + '00').slice(0, 2), 10);
};
const parseDate = (s) => {
  const m = String(s).trim().match(/^([0-9]{1,2}) ([A-Za-z]{3}) ([0-9]{4})(?: ([0-9]{2}):([0-9]{2}))?$/);
  if (!m || !MON[m[2]]) return { real: false, iso: null, time: '' };
  const d = parseInt(m[1], 10), mo = MON[m[2]], y = parseInt(m[3], 10);
  const dt = new Date(Date.UTC(y, mo - 1, d));
  const real = dt.getUTCFullYear() === y && dt.getUTCMonth() === mo - 1 && dt.getUTCDate() === d;
  const iso = real ? y + '-' + String(mo).padStart(2, '0') + '-' + String(d).padStart(2, '0') : null;
  return { real: real, iso: iso, time: m[4] ? m[4] + ':' + m[5] : '' };
};
const problems = [];
const recs = [];
let cur = null;
let trailer = null;
for (const raw of String(text).split('\n')) {
  const line = raw.trim();
  if (line.indexOf('@@ END') === 0) {
    trailer = {};
    for (const m of line.matchAll(/([A-Za-z]+)=([0-9O ,.]+?)(?=\s+[A-Za-z]+=|$)/g)) trailer[m[1]] = m[2].trim();
    cur = null;
    continue;
