export default ({ recs }) => {
  const latest = new Map();
  const tie = [];
  for (const r of recs) {
    const p = latest.get(r.ref);
    if (!p) { latest.set(r.ref, r); continue; }
    if (r.updatedKey === p.updatedKey) tie.push(r.ref);
    if (r.updatedKey > p.updatedKey) latest.set(r.ref, r);
  }
  const current = [...latest.values()].sort((a, b) => (a.ref < b.ref ? -1 : a.ref > b.ref ? 1 : 0));
  const quarantine = current.filter((r) => !r.placedReal).map((r) => r.ref);
  const candidates = current.filter((r) => r.placedReal && r.placedIso <= '2025-08-23').map((r) => ({ ref: r.ref, notes: r.notes }));
