export default ({ rows, judged, quarantine, channel }) => {
  const RATE = { EUR: 10687, GBP: 12577, USD: 10000 };
  const ALLOWED = ['awaiting_intake', 'awaiting_customer', 'dispatched'];
  const st = new Map(judged.map((j) => [j.ref, j.status]));
  const byRef = (a, b) => (a.ref < b.ref ? -1 : a.ref > b.ref ? 1 : 0);
  const imp = [];
  for (const r of rows) {
    if (!r.placedReal || r.placedIso > '2025-08-23') continue;
    const s = st.get(r.ref);
    if (s === 'cancelled') continue;
    if (!ALLOWED.includes(s)) throw new Error('no valid status for ' + r.ref + ': ' + s);
    const usd = Math.floor((r.cents * RATE[r.curr] + 5000) / 10000);
    imp.push({ ref: r.ref, placed: r.placedIso, status: s, usd_cents: usd });
  }
  imp.sort(byRef);
  const q = [...quarantine].sort();
  const total = imp.reduce((a, x) => a + x.usd_cents, 0);
  return { channel: String(channel).trim(), import: imp, quarantine: q, totals: { orders: imp.length, usd_cents: total } };
}

export default ({ parsed, current, result }) => {
  const problems = [...parsed.parse_problems, ...current.tie_problems];
  if (!parsed.reconciles) problems.push('trailer control does not reconcile: ' + JSON.stringify(parsed.control));
  const ALLOWED = ['awaiting_intake', 'awaiting_customer', 'dispatched'];
  const refs = new Set(parsed.recs.map((r) => r.ref));
  for (const x of result.import) {
    if (!ALLOWED.includes(x.status)) problems.push('bad status ' + x.ref);
    if (!refs.has(x.ref)) problems.push('unknown ref ' + x.ref);
    if (!Number.isInteger(x.usd_cents)) problems.push('bad usd ' + x.ref);
    if (!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(x.placed) || x.placed > '2025-08-23') problems.push('bad placed ' + x.ref);
  }
  if (result.totals.orders !== result.import.length) problems.push('order count mismatch');
  const sum = result.import.reduce((a, x) => a + x.usd_cents, 0);
  if (result.totals.usd_cents !== sum) problems.push('usd sum mismatch');
  for (const q of result.quarantine) if (!refs.has(q)) problems.push('unknown quarantine ref ' + q);
  return { ok: problems.length === 0, problems: problems };
}

