export default ({ text }) => {
const CUT = '2025-05-19';
const RATE = { EUR: 10669, GBP: 12654, USD: 10000 };
const toMinor = (s) => {
const t = String(s == null ? '' : s).replace(/[Oo]/g, '0');
const m = /^(\d{1,3}(?:\.\d{3})*|\d+),(\d{2})$/.exec(t);
if (!m) throw new Error('bad amount: ' + s);
return parseInt(m[1].replace(/\./g, ''), 10) * 100 + parseInt(m[2], 10);
};
const isoDate = (s) => {
const m = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(String(s == null ? '' : s));
if (!m) return null;
const d = Number(m[1]), mo = Number(m[2]), y = Number(m[3]);
const dt = new Date(Date.UTC(y, mo - 1, d));
if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== mo - 1 || dt.getUTCDate() !== d) return null;
return y + '-' + String(mo).padStart(2, '0') + '-' + String(d).padStart(2, '0');
};
const stamp = (s) => {
const m = /^(\d{2})\/(\d{2})\/(\d{4}) (\d{2}):(\d{2})$/.exec(String(s == null ? '' : s));
if (!m) throw new Error('bad UPDATED_AT: ' + s);
return m[3] + '-' + m[2] + '-' + m[1] + ' ' + m[4] + ':' + m[5];
};
const lines = String(text).split(/\r?\n/);
const recs = [];
let cur = null;
let trailer = null;
for (const raw of lines) {
const line = raw.replace(/\s+$/, '');
if (line.indexOf('@@ RECORD') === 0) { cur = {}; recs.push(cur); continue; }
if (line.indexOf('@@ END') === 0) { trailer = line; cur = null; continue; }
if (cur === null) continue;
const i = line.indexOf(':');
if (i < 0) continue;
cur[line.slice(0, i).trim()] = line.slice(i + 1).trim();
}
if (recs.length === 0) throw new Error('no records');
const all = recs.map((r, idx) => {
const c = (r['Currency'] || '') === '' ? 'GBP' : r['Currency'];
if (!RATE[c]) throw new Error('bad currency: ' + c);
return { idx: idx, ref: r['OrderNo'] || '', placed: isoDate(r['DATE_PLACED']), note: r['Status Note'] || '', updated: stamp(r['UPDATED_AT']), cur: c, minor: toMinor(r['Gross']) };
});
const best = new Map();
for (const r of all) {
if (!r.ref) throw new Error('missing OrderNo at record ' + r.idx);
const b = best.get(r.ref);
if (!b) { best.set(r.ref, r); continue; }
if (b.updated === r.updated) throw new Error('tie on ' + r.ref);
if (r.updated > b.updated) best.set(r.ref, r);
}
const current = [...best.values()].sort((a, b) => (a.ref < b.ref ? -1 : a.ref > b.ref ? 1 : 0));
const quarantine = current.filter(r => r.placed === null).map(r => r.ref);
const cands = current.filter(r => r.placed !== null && r.placed <= CUT).map(r => ({ ref: r.ref, placed: r.placed, note: r.note, usd_cents: Math.floor((r.minor * RATE[r.cur] + 5000) / 10000) }));
const sums = { EUR: 0, GBP: 0, USD: 0 };
for (const r of all) sums[r.cur] += r.minor;
const controlProblems = [];
const ctl = /^@@ END records=(\d+) EUR=(\S+) GBP=(\S+) USD=(\S+)$/.exec(trailer || '');
if (!ctl) controlProblems.push('no control trailer');
else {
if (Number(ctl[1]) !== recs.length) controlProblems.push('record count ' + recs.length + ' vs ' + ctl[1]);
for (const [k, v] of [['EUR', ctl[2]], ['GBP', ctl[3]], ['USD', ctl[4]]]) {
if (toMinor(v) !== sums[k]) controlProblems.push(k + ' sum mismatch');
}
}
return { cands: cands, quarantine: quarantine, allRefs: [...best.keys()], controlProblems: controlProblems };
};

export default ({ rows, quarantine, channel }) => {
const LABELS = ['awaiting_intake', 'awaiting_customer', 'dispatched', 'cancelled'];
const imp = [];
for (const r of rows) {
if (!LABELS.includes(r.status)) throw new Error('bad label for ' + r.ref);
if (r.status === 'cancelled') continue;
imp.push({ ref: r.ref, placed: r.placed, status: r.status, usd_cents: r.usd_cents });
}
imp.sort((a, b) => (a.ref < b.ref ? -1 : a.ref > b.ref ? 1 : 0));
const q = [...quarantine].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
const total = imp.reduce((a, r) => a + r.usd_cents, 0);
return { channel: channel, import: imp, quarantine: q, totals: { orders: imp.length, usd_cents: total } };
};

export default ({ answer, split }) => {
const problems = [...split.controlProblems];
const refs = new Set(split.allRefs);
const seen = new Set();
const imp = answer.import;
if (answer.totals.orders !== imp.length) problems.push('order count mismatch');
if (answer.totals.usd_cents !== imp.reduce((a, r) => a + r.usd_cents, 0)) problems.push('usd total mismatch');
for (const r of imp) {
if (!refs.has(r.ref)) problems.push('unknown ref ' + r.ref);
if (seen.has(r.ref)) problems.push('duplicate ' + r.ref);
seen.add(r.ref);
}
for (const q of answer.quarantine) {
if (!refs.has(q)) problems.push('unknown quarantine ref ' + q);
if (seen.has(q)) problems.push('ref both imported and quarantined ' + q);
}
return problems.length === 0 ? true : { ok: false, problems: problems };
};

