export default ({ text }) => {
const NL = String.fromCharCode(10);
const CR = String.fromCharCode(13);
const lines = String(text).split(NL).map(l => l.split(CR).join(''));
const isDigits = (g) => g.length > 0 && g.split('').every(c => c >= '0' && c <= '9');
const cents = (raw) => {
  const s = String(raw === undefined ? '' : raw).split('O').join('0').trim();
  const parts = s.split(',');
  if (parts.length !== 2 || parts[1].length !== 2 || !isDigits(parts[1])) throw new Error('bad amount: ' + raw);
  const ip = parts[0].split('.');
  const ok = ip.length === 1 ? isDigits(ip[0]) : ip.every((g, i) => isDigits(g) && (i === 0 ? g.length <= 3 : g.length === 3));
  if (!ok) throw new Error('bad amount: ' + raw);
  return Number(ip.join('')) * 100 + Number(parts[1]);
};
const ymd = (raw) => {
  const p = String(raw === undefined ? '' : raw).split('/');
  if (p.length !== 3 || p[0].length !== 2 || p[1].length !== 2 || p[2].length !== 4 || !p.every(g => isDigits(g))) return null;
  const d = Number(p[0]), mo = Number(p[1]), y = Number(p[2]);
  const dt = new Date(Date.UTC(y, mo - 1, d));
  if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== mo - 1 || dt.getUTCDate() !== d) return null;
  return y * 10000 + mo * 100 + d;
};
const rowKey = (raw) => {
  const rt = String(raw === undefined ? '' : raw).split(' ');
  if (rt.length !== 2) throw new Error('bad row time: ' + raw);
  const d = ymd(rt[0]);
  const hm = rt[1].split(':');
  if (d === null || hm.length !== 2 || !isDigits(hm[0]) || !isDigits(hm[1])) throw new Error('bad row time: ' + raw);
  return d * 10000 + Number(hm[0]) * 100 + Number(hm[1]);
};
const recs = [];
let cur = null;
for (const line of lines) {
  if (line.indexOf('@@ RECORD ') === 0) { cur = { n: Number(line.slice(10).trim()), f: {} }; recs.push(cur); continue; }
  if (line.indexOf('@@ END') === 0) { cur = null; continue; }
  if (!cur) continue;
  const i = line.indexOf(':');
  if (i < 0) continue;
  cur.f[line.slice(0, i).trim()] = line.slice(i + 1).trim();
}
const rows = recs.map(r => {
  const f = r.f;
  const ccyRaw = (f['CCY'] || '').trim();
  const ccy = ccyRaw === '' ? 'EUR' : ccyRaw;
  if (['EUR', 'GBP', 'USD'].indexOf(ccy) < 0) throw new Error('bad currency: ' + ccy);
  const ref = f['Order Ref'];
  if (!ref) throw new Error('missing ref in record ' + r.n);
  const placedNum = ymd(f['DATE_PLACED']);
  const s = placedNum === null ? null : String(placedNum);
  return { n: r.n, ref: ref, rowKey: rowKey(f['Row Time']), placedNum: placedNum, placed: s === null ? null : s.slice(0, 4) + '-' + s.slice(4, 6) + '-' + s.slice(6, 8), cents: cents(f['Gross']), ccy: ccy, note: f['Status Note'] || '' };
});
const trailerLine = lines.filter(l => l.indexOf('@@ END') === 0)[0];
if (!trailerLine) throw new Error('missing trailer');
const control = { records: 0, EUR: 0, GBP: 0, USD: 0 };
trailerLine.split(' ').slice(2).forEach(t => {
  const eq = t.indexOf('=');
  const k = t.slice(0, eq);
  const v = t.slice(eq + 1);
  if (k === 'records') control.records = Number(v); else control[k] = cents(v);
});
return { rows: rows, control: control };
}

